package target

import (
	"bytes"
	"fmt"
	"strconv"
	"strings"
)

// CursorRulesDir is where the cursor target writes, under a qm/ subdirectory so
// generated files are unambiguous.
const CursorRulesDir = ".cursor/rules/qm"

// cursor renders Cursor .mdc rule files.
//
// Cursor's frontmatter has a globs field it watches and an alwaysApply flag. A
// resident rule sets alwaysApply true and declares no globs; a scoped rule lists
// its globs and leaves alwaysApply false. The body is the document's prose
// verbatim, the same text the claude target emits.
type cursor struct{}

func (cursor) Name() string { return "cursor" }

func (cursor) IgnorePaths() []string { return []string{CursorRulesDir + "/"} }

func (cursor) Render(in Input) (Output, error) {
	files := make([]File, 0, len(in.Docs))
	for _, d := range in.Docs {
		files = append(files, File{
			Path: fmt.Sprintf("%s/%s.mdc", CursorRulesDir, d.ID),
			Body: renderCursorRule(d),
		})
	}
	return Output{Files: files}, nil
}

func renderCursorRule(d Doc) []byte {
	var b bytes.Buffer

	b.WriteString("---\n")
	fmt.Fprintf(&b, "# Generated by Quartermaster. Do not edit; edit the source document instead.\n")
	fmt.Fprintf(&b, "# source: %s  bundle: %s", d.ID, d.Digest)
	if d.Commit != "" {
		fmt.Fprintf(&b, "  commit: %s", d.Commit)
	}
	b.WriteByte('\n')

	if d.Description != "" {
		fmt.Fprintf(&b, "description: %s\n", strconv.Quote(d.Description))
	}
	if len(d.Scope) > 0 {
		fmt.Fprintf(&b, "globs: %s\n", strings.Join(d.Scope, ","))
		b.WriteString("alwaysApply: false\n")
	} else {
		b.WriteString("alwaysApply: true\n")
	}
	b.WriteString("---\n\n")

	prose := bytes.TrimLeft(d.Prose, "\n")
	b.Write(prose)
	if !bytes.HasSuffix(prose, []byte("\n")) {
		b.WriteByte('\n')
	}

	return b.Bytes()
}
